python3 -I -c 'import json,pathlib,hashlib,collections,os; errors=[]; totals=collections.Counter(); dims={"correctness":"answer_correctness","grounding":"source_grounding","fidelity":"reading_fidelity"}; outcomes=("correct","partial","incorrect","missing","unsupported","unverified","error")
def check(ok,msg):
 if not ok: errors.append(msg)
def pointer(doc,p):
 for part in p.lstrip("/").split("/") if p else []:
  part=part.replace("~1","/").replace("~0","~"); doc=doc[int(part)] if isinstance(doc,list) else doc[part]
 return doc
def walk(x,loc):
 if isinstance(x,dict):
  if "inventory" in x and "json_pointer" in x:
   totals["inventory_pointers"]+=1
   try:
    p=pathlib.Path(x["inventory"]); check(p.parent==pathlib.Path("benchmark/cases/dev"),loc+" inventory outside dev"); row=pointer(json.loads(p.read_text()),x["json_pointer"])
    if "literal" in x: check(x["literal"]==row["atomic_fact"],loc+" literal mismatch")
    if "citations" in x: check(x["citations"]==row["citations"],loc+" citations mismatch")
   except Exception as e: errors.append(loc+" unresolved "+str(e))
  for k,v in x.items(): walk(v,loc+"/"+k)
 elif isinstance(x,list):
  for i,v in enumerate(x): walk(v,loc+"/"+str(i))
def aggregate(items,extra):
